 tag_errors+=tag>>3!=2;parity_errors+=not parity;gaps+=last is not None and counter!=(last+1)&3;saturations+=sum(x in [-32768,32767] for x in xyz);last=counter
 words.append({'index':i,'tag_hex':f'{tag:02X}','tag_id':tag>>3,'counter':counter,'parity_even':parity,'x_lsb':xyz[0],'y_lsb':xyz[1],'z_lsb':xyz[2],'accepted':False,'reason':'Post-burst grouped configuration refused; not a valid window'})
